contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function driving the test
    // params: depositor address is msg.sender of this call; amount to send
    function checkDepositIncreasesBalance(uint amount) public payable {
        // ensure this contract has enough balance to forward
        require(address(this).balance >= amount);

        // read balance before
        uint before = c.balances(address(this));

        // perform deposit by calling receive/Deposit with value
        c.Deposit{value: amount}();

        // read balance after
        uint after = c.balances(address(this));

        // on original contract P, after >= before + amount
        // on mutant M (which omitted balances update) this will fail when amount>0
        assert(after >= before + amount);
    }

    // allow funding this test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // params: amount to attempt to collect (colAmt) and amount to deposit (depAmt)
    function run(uint colAmt, uint depAmt) public payable {
        require(address(this).balance >= depAmt);
        // Record contract balance before actions
        uint before = address(c).balance;
        // Call Collect: may transfer ETH out of c to this contract/other externally
        c.Collect(colAmt);
        // Call Deposit sending depAmt to c
        c.Deposit{value: depAmt}();
        // After Deposit, the contract's ETH balance must have increased by exactly depAmt
        // This holds for the original contract where Deposit forwards the Ether into c.
        uint after = address(c).balance;
        assert(after == before - 0 + depAmt);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint collectAmt, uint depositAmt) public payable {
        require(address(this).balance >= depositAmt);
        // First call: attempt to collect (may revert inside C if conditions not met);
        // we call with zero value as Collect is payable but sends funds out of C.
        c.Collect(collectAmt);
        // Record contract balance before Deposit
        uint before = address(c).balance;
        // Deposit depositAmt wei into C
        c.Deposit{value: depositAmt}();
        uint afterBalance = address(c).balance;
        // General rule: after deposit, contract's balance increased by at least depositAmt
        // (original contract increments internal balance and receives funds; mutant skips updating internal balance
        // but still should receive the Ether in normal Deposit; mutant breaks this observable rule)
        assert(afterBalance >= before + depositAmt);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller is msg.sender of test contract when interacting; we use two parameters:
    // addr - the account used to interact with C (must be the same as msg.sender of this tx in practice),
    // dep - the amount of wei to send with Deposit. Collect amount is arbitrary but must be nonzero to potentially observe differences.
    function run(uint _collectAmt, uint _dep) public payable {
        require(true);
        // attempt to call Collect then Deposit; send Ether with Deposit
        // ensure this contract has enough balance to forward
        require(address(this).balance >= _dep);

        // Call Collect first (may revert silently if conditions not met in C - we don't capture revert flag here)
        c.Collect(_collectAmt);

        // Now call Deposit sending _dep wei
        c.Deposit{value: _dep}();

        // After these operations, the invariant in the original contract is that the caller's recorded balance
        // reflects the deposit: balances(msg.sender) >= previous balances + _dep. We cannot read previous balances here,
        // but we can observe that the caller's recorded balance is at least the amount deposited if Collect could not have
        // increased balances beyond the deposit (Collect only decreases balances). Thus we assert that the caller's
        // recorded balance is >= _dep. This is violated by the mutant which fails to update balances on Deposit.
        assert(c.balances(address(this)) >= _dep);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test driving calls and ending with one assert
    function runTest(uint depositAmount) public payable {
        // ensure this contract has enough ETH to forward
        require(address(this).balance >= depositAmount);

        // read initial balance for this contract as the depositor
        uint before = c.balances(address(this));

        // perform deposit on target contract c, forwarding depositAmount
        c.Deposit{value: depositAmount}();

        // read balance after deposit
        uint after = c.balances(address(this));

        // rule: the depositor's balance must have increased exactly by depositAmount
        assert(after == before + depositAmount);
    }

    // allow the test contract to receive ETH so it can call c.Deposit{value:...}
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        // call Deposit sending `amount` wei
        c.Deposit{value: amount}();
        // In the original contract Deposit increments balances[msg.sender] by amount.
        // So the public getter balances(address) for this test contract should reflect that.
        uint bal = c.balances(address(this));
        assert(bal >= amount && bal % amount == 0);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: depositor address, initial deposit amount, second deposit amount
    function run(address depositor, uint initAmt, uint addAmt) public {
        // require sane inputs to avoid overflow and ensure deposits are meaningful
        require(depositor != address(0));
        require(initAmt > 0 && addAmt > 0);

        // ensure this contract has enough balance to forward deposits
        require(address(this).balance >= initAmt + addAmt);

        // first deposit by depositor: we must call via this contract sending ether
        // use a low-level call to instruct c to treat msg.sender as this contract
        // so we simulate depositor by making deposits from this contract but we will
        // instead rely on c.balances getter keyed by address(this). To target arbitrary
        // depositor, we require depositor == address(this)
        // Ensure depositor is this contract so c.balances[msg.sender] corresponds
        require(depositor == address(this));

        // initial deposit
        c.Deposit{value: initAmt}();

        // record balance after initial deposit
        uint balBefore = c.balances(depositor);

        // additional deposit
        c.Deposit{value: addAmt}();

        // record balance after second deposit
        uint balAfter = c.balances(depositor);

        // Property: second balance must be >= first balance (deposit doesn't reduce balance)
        assert(balAfter >= balBefore);
    }

    // allow this contract to receive ETH to fund deposits
    receive() external payable {}
}
